<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'; const props = defineProps<{ wedding: { id: number; name: string }; gifts: { id: number; name: string; description: string | null; quantity: number; reserved_quantity: number; reference_url: string | null }[] }>(); const form = useForm({ guest_name: '', guest_email: '', quantity: 1, idempotency_key: crypto.randomUUID() }); function reserve(id: number): void { form.post(route('gifts.reserve', [props.wedding.id, id]), { preserveScroll: true, onSuccess: () => { form.idempotency_key = crypto.randomUUID(); } }); }
</script>
<template><Head :title="`Regalos · ${wedding.name}`"/><main class="min-h-screen bg-[#fbf8f4] p-6 text-stone-800"><div class="mx-auto max-w-3xl"><h1 class="text-center font-serif text-4xl">Lista de regalos</h1><p class="mt-2 text-center text-stone-600">{{ wedding.name }}</p><article v-for="gift in gifts" :key="gift.id" class="mt-5 rounded-2xl border bg-white p-5"><h2 class="font-serif text-xl">{{ gift.name }}</h2><p v-if="gift.description" class="mt-1 text-sm">{{ gift.description }}</p><p class="mt-2 text-sm">Disponibles: {{ gift.quantity - gift.reserved_quantity }}</p><a v-if="gift.reference_url" :href="gift.reference_url" target="_blank" rel="noopener" class="text-sm text-rose-800 underline">Ver referencia</a><form v-if="gift.quantity > gift.reserved_quantity" class="mt-3 flex flex-wrap gap-2" @submit.prevent="reserve(gift.id)"><input v-model="form.guest_name" required class="rounded border-stone-300" placeholder="Tu nombre"><input v-model.number="form.quantity" type="number" min="1" :max="gift.quantity - gift.reserved_quantity" class="w-20 rounded border-stone-300"><button class="rounded bg-rose-800 px-3 py-2 text-sm text-white">Reservar</button></form></article></div></main></template>
